const MIN_FR = -0.00033445;
const MAX_FR = 0.00088179;

const fmt=n=>n>=0?`$${Math.abs(n).toLocaleString(undefined,{maximumFractionDigits:0})}`:`-$${Math.abs(n).toLocaleString(undefined,{maximumFractionDigits:0})}`;
const fP=n=>`${n>=0?"+":""}${n.toFixed(2)}%`;
const Tip=({active,payload,label})=>{
  if(!active||!payload?.length)return null;
  return <div style={{background:"#0a0a0f",border:"1px solid rgba(255,255,255,0.08)",borderRadius:10,padding:"10px 14px",fontSize:11,fontFamily:"'IBM Plex Mono',monospace"}}><div style={{color:"#555",marginBottom:4,fontSize:10}}>{label}</div>{payload.filter(p=>p.value!=null).map((p,i)=><div key={i} style={{color:p.color,marginTop:2}}>{p.name}: ${p.value?.toLocaleString()}</div>)}</div>;
};

// Build price lookup
const pxMap = {};
PX.forEach(([ts,px])=>{ pxMap[ts]=px; });

function getPrice(ts) {
  for (const off of [0,3600,-3600,7200,-7200,14400,-14400,28800,-28800]) {
    if (pxMap[ts+off]!==undefined) return pxMap[ts+off];
  }
  return null;
}

// Compute rebalance events from price data
function getRbEvents(threshold) {
  let lr = PX[0][1];
  const events = [];
  for (const [ts,px] of PX) {
    if (Math.abs(px-lr)/lr >= threshold) {
      events.push({ts,price:px});
      lr = px;
    }
  }
  return events;
}

// Full backtest engine in JS
function runBacktest(rbThreshold, swapFee, filterEnabled, frThreshold) {
  const ini=1000000, sapr=0.03, bapr=0.0366, tf=0.0004, wf=1, hp=8;
  const sf = swapFee;
  const ppy = 365.25*24/hp;
  const n = FR.length;
  const rbEvents = getRbEvents(rbThreshold);
  
  const iNet = ini*(1-sf);
  const ep = getPrice(FR[0][0]) || PX[0][1];
  
  let active=true, am=iNet/ep, bo=iNet*0.5, sn=bo*2, se=ep, ss=sn/se;
  let ttf=sn*tf, tsw=ini*sf;
  let ts_=0,tb=0,tfp=0,tfr_=0,rc=0,twf=0,cy=0;
  let lp=ep, rbIdx=0;
  let nPauses=0, nResumes=0, pauseCost=0, periodsPaused=0, usdcEq=0;
  const cexFixed = 500;
  
  const dailyMap = {};
  
  for (let i=0; i<n; i++) {
    const [fts, fr] = FR[i];
    let px = getPrice(fts);
    if (px) lp=px; else px=lp;
    
    // Date key for daily aggregation
    const d = new Date(fts*1000);
    const dk = String(d.getUTCMonth()+1).padStart(2,'0')+'-'+String(d.getUTCDate()).padStart(2,'0');
    
    // FUNDING FILTER
    if (filterEnabled) {
      if (active && fr < frThreshold) {
        // PAUSE
        nPauses++;
        const ip=am*(px-se), sp=ss*(se-px);
        let eq=ini+cy-ttf-twf-tsw+ip+sp;
        let pc;
        if (sf>0) {
          const cn=ss*px, cf=cn*tf, pSw=eq*sf;
          ttf+=cf; tsw+=pSw; twf+=wf;
          pc=cf+pSw+wf;
        } else {
          pc=cexFixed;
        }
        pauseCost+=pc;
        usdcEq=eq-pc;
        cy=usdcEq-ini+ttf+twf+tsw;
        active=false;
        if(!dailyMap[dk])dailyMap[dk]={date:dk,equity:0,fr:0,pnl:0,price:0,bc:0,ec:0,sy:0};
        dailyMap[dk].equity=Math.round(usdcEq);
        dailyMap[dk].fr+=0;
        dailyMap[dk].pnl+=Math.round(-pc);
        dailyMap[dk].ec+=Math.round(pc);
        dailyMap[dk].price=px;
        continue;
      }
      if (!active && fr >= frThreshold) {
        // RESUME
        nResumes++;
        let rc2;
        if (sf>0) {
          const rSw=usdcEq*sf, after=usdcEq-rSw;
          se=px; am=after/px; bo=after*0.5; sn=bo*2; ss=sn/px;
          const of=sn*tf;
          ttf+=of; tsw+=rSw; twf+=wf;
          rc2=of+rSw+wf;
        } else {
          rc2=cexFixed;
          const after=usdcEq-rc2;
          se=px; am=after/px; bo=after*0.5; sn=bo*2; ss=sn/px;
        }
        pauseCost+=rc2;
        const after2 = sf>0 ? (usdcEq-usdcEq*sf-sn*tf-wf+usdcEq*sf) : (usdcEq-rc2);
        cy=(usdcEq-rc2)-ini+ttf+twf+tsw;
        active=true;
        if(!dailyMap[dk])dailyMap[dk]={date:dk,equity:0,fr:0,pnl:0,price:0,bc:0,ec:0,sy:0};
        dailyMap[dk].equity=Math.round(usdcEq-rc2);
        dailyMap[dk].fr+=0;
        dailyMap[dk].pnl+=Math.round(-rc2);
        dailyMap[dk].ec+=Math.round(rc2);
        dailyMap[dk].price=px;
        continue;
      }
      if (!active) {
        periodsPaused++;
        if(!dailyMap[dk])dailyMap[dk]={date:dk,equity:0,fr:0,pnl:0,price:0,bc:0,ec:0,sy:0};
        dailyMap[dk].equity=Math.round(usdcEq);
        dailyMap[dk].fr+=0;
        dailyMap[dk].price=px;
        continue;
      }
    }
    
    // NORMAL
    const sy=(am*se)*(sapr/ppy); ts_+=sy;
    const bc=bo*(bapr/ppy); tb+=bc;
    const fp=sn*fr;
    if (fr<0) tfp+=Math.abs(fp); else tfr_+=fp;
    const ip=am*(px-se), sp=ss*(se-px);
    const pn=sy-bc+fp; cy+=pn;
    const eq=ini+cy-ttf-twf-tsw+ip+sp;
    
    if(!dailyMap[dk])dailyMap[dk]={date:dk,equity:0,fr:0,pnl:0,price:0,bc:0,ec:0,sy:0};
    dailyMap[dk].equity=Math.round(eq);
    dailyMap[dk].fr+=Math.round(fp);
    dailyMap[dk].pnl+=Math.round(pn);
    dailyMap[dk].bc+=Math.round(bc);
    dailyMap[dk].sy+=Math.round(sy);
    dailyMap[dk].price=px;
    
    // Rebalance
    while (rbIdx<rbEvents.length && rbEvents[rbIdx].ts<=fts) {
      const rpx=rbEvents[rbIdx].price; rc++;
      const cn=ss*rpx, cf=cn*tf; twf+=wf;
      const sc=eq*sf*2; tsw+=sc;
      const ea=eq-sc;
      se=rpx; am=ea/rpx; bo=ea*0.5; sn=bo*2; ss=sn/rpx;
      const of=sn*tf; ttf+=cf+of;
      dailyMap[dk].ec+=Math.round(cf+of+wf+sc);
      rbIdx++;
    }
  }
  
  const dd = Object.values(dailyMap);
  // Compute cumulatives
  let cFr=0, cBc=0, cEc=0, cSy=0, cNet=0;
  // Add entry costs to first day exec
  if(dd.length>0) dd[0].ec += Math.round(ini*sf + (ini*(1-sf)/ep)*ep*tf);
  for (const d of dd) {
    cFr += (d.fr||0); cBc += (d.bc||0); cEc += (d.ec||0); cSy += (d.sy||0);
    cNet = cFr - cBc - cEc + cSy;
    d.cFr = cFr; d.cBc = -cBc; d.cEc = -cEc; d.cSy = cSy; d.cNet = cNet;
  }
  const td = dd.length;
  const fe = dd[dd.length-1]?.equity || ini;
  const tr = (fe-ini)/ini;
  const ar = tr*(365/td);
  
  let pk=-Infinity, mdd=0;
  for (const d of dd) {
    if (d.equity>pk) pk=d.equity;
    const dr=(pk-d.equity)/pk;
    if (dr>mdd) mdd=dr;
  }
  
  const af = 365/td;
  return {
    dd,
    s: {
      apy: Math.round(ar*10000)/100,
      pnl: Math.round(fe-ini),
      rb: rc,
      fees: Math.round(ttf+tsw),
      swap: Math.round(tsw),
      taker: Math.round(ttf),
      mdd: Math.round(mdd*10000)/100,
      funding: Math.round((tfr_-tfp)/ini*100*af*100)/100,
      staking: Math.round(ts_/ini*100*af*100)/100,
      borrow: Math.round(tb/ini*100*af*100)/100,
      feePct: Math.round((ttf+tsw)/ini*100*af*100)/100,
      nPauses, nResumes,
      pauseCost: Math.round(pauseCost),
      daysPaused: Math.round(periodsPaused*hp/24*10)/10,
      totalStaking: Math.round(ts_),
      totalBorrow: Math.round(tb),
      totalFundingRecv: Math.round(tfr_),
      totalFundingPaid: Math.round(tfp),
      netFunding: Math.round(tfr_-tfp),
    }
  };
}

